#include <stdio.h>

struct Point {
    int x;
    int y;
};

static int manhattan(struct Point p) {
    int ax = p.x < 0 ? -p.x : p.x;
    int ay = p.y < 0 ? -p.y : p.y;
    return ax + ay;
}

int main(void) {
    struct Point p;
    if (scanf("%d %d", &p.x, &p.y) != 2) return 0;
    printf("%d\n", manhattan(p));
    return 0;
}

