struct Student {
    int id;
    int m1, m2, m3;
};

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    struct Student s[100];
    for (int i = 0; i < n; i++) {
        if (scanf("%d %d %d %d", &s[i].id, &s[i].m1, &s[i].m2, &s[i].m3) != 4) return 0;
    }
    int best_idx = 0;
    int best_total = s[0].m1 + s[0].m2 + s[0].m3;
    for (int i = 1; i < n; i++) {
        int total = s[i].m1 + s[i].m2 + s[i].m3;
        if (total > best_total) {
            best_total = total;
            best_idx = i;
        }
    }
    printf("%d\n", s[best_idx].id);
    return 0;
}

