#include <stdio.h>

struct Student {
    int id;
    int marks;
};

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    struct Student s[100];
    for (int i = 0; i < n; i++) {
        if (scanf("%d %d", &s[i].id, &s[i].marks) != 2) return 0;
    }
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (s[j].marks > s[j + 1].marks) {
                struct Student tmp = s[j];
                s[j] = s[j + 1];
                s[j + 1] = tmp;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (i) putchar(' ');
        printf("%d", s[i].id);
    }
    putchar('\n');
    return 0;
}

