#include <stdio.h>

struct Student {
    int id;
    int marks;
};

static int count_passed(struct Student arr[], int n) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i].marks >= 40) count++;
    }
    return count;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    struct Student s[100];
    for (int i = 0; i < n; i++) {
        if (scanf("%d %d", &s[i].id, &s[i].marks) != 2) return 0;
    }
    printf("%d\n", count_passed(s, n));
    return 0;
}
